sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float reach;
uniform float threshold;
uniform float intensity;
uniform float blend;
uniform float style;
layout(color) uniform half4 thresholdAdd;
layout(color) uniform half4 color;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 classic(float2 coord) {
    half4 src = image.eval(coord);
    float2 c = center * size;
    float length_ = max(reach, 0.0);
    float sum = 0.0;
    for (int i = 0; i < 48; i++) {
        float t = float(i) / 47.0;
        half4 s = image.eval(c + (coord - c) * (1.0 - length_ * t / (1.0 + length_)));
        float l = s.a > 0.0 ? luma(float3(s.rgb) / float(s.a)) * float(s.a) : 0.0;
        sum += max(l - threshold, 0.0) / max(1.0 - threshold, 0.001) * (1.0 - t);
    }
    float g = clamp(sum / 24.0 * intensity * float(color.a), 0.0, 1.0);
    float a = float(src.a);
    float3 base = a > 0.0 ? float3(src.rgb) / a : float3(0.0);
    float3 light = float3(color.rgb) * g;
    float outA = max(a, g);
    float3 rgb = outA > 0.0 ? (base * a + light - base * a * light) / outA : float3(0.0);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * half(outA), half(outA));
}
half4 main(float2 p) {
    if (style < 0.5) return classic(p);
    float4 src = float4(image.eval(p));
    float len = clamp(reach, 0.0, 1000.0);
    float gain = clamp(intensity, 0.0, 100.0) * clamp(float(color.a), 0.0, 1.0) * clamp(len * 100.0, 0.0, 1.0);
    if (!(gain > 0.0)) return half4(src);
    float2 c = clamp(center, float2(-8.0), float2(9.0)) * size;
    float2 d = p - c;
    float f = len / (len + 0.1);
    float n = clamp(ceil(f * length(d) / 3.0), 1.0, 48.0);
    float j = fract(dot(p, float2(0.7548777, 0.5698403)));
    float thr = clamp(threshold + luma(float3(thresholdAdd.rgb)), 0.04, 2.0);
    float knee = thr - 0.04;
    float2 stride = d * (f / n);
    float2 q = p - stride * j;
    float w = n - j;
    float4 acc = float4(0.0);
    for (int i = 0; i < 48; i++) {
        if (float(i) >= n) break;
        float4 s = float4(image.eval(q));
        float g = s.a > 0.0 ? smoothstep(knee, thr, luma(s.rgb) / max(s.a, 0.000001)) : 0.0;
        acc += (w * g) * s;
        q -= stride;
        w -= 1.0;
    }
    acc.rgb = mix(acc.rgb, float3(color.rgb) * luma(acc.rgb), clamp(blend, 0.0, 1.0));
    float4 o = src + acc * (gain * 0.5 / max(n * (n + 1.0) * 0.5 - n * j, 0.0001));
    o.a = clamp(o.a, 0.0, 1.0);
    o.rgb = clamp(o.rgb, float3(0.0), float3(o.a));
    return half4(o);
}
